def file_name_check(file_name):
    if file_name.count('.') != 1:
        return 'No'

    before, after = file_name.split('.')

    if not before or not ('a' <= before[0] <= 'z' or 'A' <= before[0] <= 'Z'):
        return 'No'

    if after not in ['txt', 'exe', 'dll']:
        return 'No'

    if sum(c.isdigit() for c in file_name) > 3:
        return 'No'

    return 'Yes'
